def label(name, rows, extra, ns, col="#C0392B", w="100%"):
    tr = "".join(f'<tr><td style="padding:.6mm 2mm;{"padding-left:6mm;font-style:italic" if r[0].startswith("dont") else ""}">{r[0]}</td><td style="padding:.6mm 2mm;text-align:right">{r[1]}</td><td style="padding:.6mm 2mm;text-align:right">{r[2]}</td></tr>' for r in rows)
    nsb = "".join(f'<span style="display:inline-block;width:{"8mm" if k == ns else "5.5mm"};height:{"8mm" if k == ns else "5.5mm"};line-height:{"8mm" if k == ns else "5.5mm"};text-align:center;color:#fff;font-weight:800;border-radius:1mm;background:{c};vertical-align:middle">{k}</span>' for k, c in zip("ABCDE", ["#038141", "#85BB2F", "#FECB02", "#EE8100", "#E63E11"]))
    return f'''<div class="doc" style="transform:none;border:2px solid {col};background:#fff;padding:2.5mm 3.5mm;font-size:9.4pt;width:{w};box-sizing:border-box">
<div class="flex" style="justify-content:space-between;align-items:center"><b style="font-size:12.5pt;color:{col}">{name}</b><span style="background:#f2f2f2;border-radius:1.5mm;padding:.8mm 1.5mm"><b class="xs">NUTRI-SCORE</b> {nsb}</span></div>
<table style="width:100%;border-collapse:collapse;margin-top:1.5mm;font-size:9pt" border="1"><tr style="background:#f2f2f2"><th style="text-align:left;padding:.6mm 2mm">Valeurs nutritionnelles</th><th style="padding:.6mm 2mm">pour 100 g</th><th style="padding:.6mm 2mm">par portion (30 g)</th></tr>{tr}</table>{extra}</div>'''


CROQ = [("Énergie", "1 650 kJ / 392 kcal", "495 kJ / 118 kcal"), ("Matières grasses", "6,5 g", "2 g"), ("dont acides gras saturés", "2,1 g", "0,6 g"), ("Glucides", "74 g", "22 g"), ("dont sucres", "24 g", "7,2 g"), ("Fibres alimentaires", "6 g", "1,8 g"), ("Protéines", "8 g", "2,4 g"), ("Sel", "0,6 g", "0,18 g")]
MUES = [("Énergie", "1 540 kJ / 366 kcal", "462 kJ / 110 kcal"), ("Matières grasses", "6 g", "1,8 g"), ("dont acides gras saturés", "1 g", "0,3 g"), ("Glucides", "60 g", "18 g"), ("dont sucres", "12 g", "3,6 g"), ("Fibres alimentaires", "9 g", "2,7 g"), ("Protéines", "11 g", "3,3 g"), ("Sel", "0,1 g", "0,03 g")]


def pyramide():
    lv = [("🍬🥤🍟", "Les extras : de temps en temps, en petite quantité", "#D9534F", 72), ("🫒🥜", "Les matières grasses : un peu (huile, noix)", "#E8A33D", 92), ("🥛🧀🫘🐟🥚🍗", "Produits laitiers et protéines : un peu à chaque repas", "#4A7BD1", 112),
          ("🍞🍚🥔", "Céréales (de préférence complètes), pommes de terre : à chaque repas", "#C9A227", 132), ("🥦🥕🍎🍌", "Légumes et fruits : beaucoup, à chaque repas", "#3E8E41", 152), ("💧", "L'eau : la seule boisson indispensable, toute la journée", "#2E86AB", 172)]
    return '<div style="display:flex;flex-direction:column;align-items:center;gap:1.2mm">' + "".join(
        f'<div style="width:{w}mm;box-sizing:border-box;background:{c};color:#fff;border-radius:2mm;padding:1.2mm 2mm;text-align:center;font-size:9.4pt;line-height:1.2"><span style="font-size:12pt">{e}</span> <b>{t}</b></div>' for e, t, c, w in lv) + '</div>'


def build_v2m9(start=1, tstart=1, render=True):
    b = Book("V2 · M9", "Volume 2 · Je me débrouille · Module 9 · Bien manger", MC, start=start)
    E = Ex(b)
    vis = ('<div class="flex" style="justify-content:space-around;align-items:flex-end">' + avatar("amina", 80, "rire") + '<div style="font-size:34pt">🥙🫓</div>' + avatar("yonas", 80, "sourire") + '<div style="font-size:34pt">🍲🥗</div>'
           + avatar("mateo", 80, "surpris") + '<div style="font-size:34pt">🍟🧇</div>' + avatar("daria", 80, "sourire") + '</div>')
    opening(b, MC, 9, "Bien manger", vis, [("🏷️", "lire une étiquette et comparer deux produits"), ("💡", "donner un conseil : il faut, tu devrais, évite de…"), ("⚖️", "parler des quantités : du, de la, un kilo de, un peu de…"),
            ("🍲", "comprendre et écrire une recette"), ("😋", "parler des goûts, des saveurs et des plats du monde"), ("📊", "lire un tableau de données")],
            ["Qu'est-ce que tu as mangé ce matin ?", "Quel est ton plat préféré ? Il vient de quel pays ?", "Pour toi, qu'est-ce que « bien manger » ?"],
            ["un aliment", "un repas", "le goût", "sucré", "salé", "une recette", "une étiquette", "il faut", "tu devrais", "un peu de"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("mateo", ["Ce midi, au dîner, j'ai pris des frites, un hamburger et un soda. Trop bon ! 😋"], "fatou", ["Encore des frites ? Tu en as mangé hier aussi !"], "rire", "surpris")),
        bd_case(2, lr("mateo", ["Et alors ? J'adore ça ! Mais à 15 h, je suis toujours fatigué en classe…"], "amina", ["C'est normal ! Tu devrais manger plus de légumes et boire de l'eau."], "pense", "sourire")),
        bd_case(3, lr("prof", ["Amina a raison. Il faut manger varié : des légumes, des fruits, des céréales, un peu de viande ou de poisson…"], "yonas", ["Et le chocolat, Madame ? 🍫"], "sourire", "rire")),
        bd_case(4, lr("prof", ["Le chocolat ? Oui, mais un peu, pas tous les jours ! Le sucre, c'est pour le plaisir."], "daria", ["Chez moi, ma mère fait du bortsch : il y a beaucoup de légumes dedans !"], "rire", "sourire")),
        bd_case(5, lr("bilal", ["Et chez nous, on mange du kabuli palaw : du riz avec des carottes et des raisins secs. C'est délicieux !"], "mateo", ["Miam ! Moi, je voudrais goûter !"], "sourire", "surpris")),
        bd_case(6, lr("prof", ["J'ai une idée : nous allons écrire le livre de recettes de la classe, avec un plat de chaque pays !"], "fatou", ["Super ! J'apporte la recette du riz sauce arachide de ma grand-mère !"], "sourire", "rire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : au dîner.", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois avec le ton (Mateo content puis fatigué, Amina qui conseille, Yonas qui plaisante). Expliquer « le dîner » = le repas de midi en Belgique. Demander : « Qu'est-ce que Mateo a mangé ? Pourquoi est-il fatigué ? Que conseille Amina ? Quel projet propose Mme Lambert ? »", sol="Activité orale.")
    b.page(f'<h2>Découvrir · Au dîner</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f'<p>1. Qu\'est-ce que Mateo a mangé ce midi ? {blank("xl")}</p><p>2. Quel est son problème à 15 h ? {blank("xl")}</p><p>3. Que lui conseille Amina ? (2 conseils) {blank("xl")}</p><p>4. Pour Mme Lambert, que faut-il faire ? {blank("xl")}</p><p>5. Qu\'est-ce qu\'il y a dans le kabuli palaw ? {blank("xl")}</p><p>6. Quel projet propose Mme Lambert ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Des frites, un hamburger et un soda. — 2. Il est toujours fatigué en classe. — 3. Manger plus de légumes et boire de l'eau. — 4. Manger varié (des légumes, des fruits, des céréales, un peu de viande ou de poisson). — 5. Du riz, des carottes et des raisins secs. — 6. Écrire le livre de recettes de la classe, avec un plat de chaque pays.")
    e2 = E("Vrai ou faux ? Je coche.", vf(["Mateo a mangé des frites deux jours de suite.", "Pour Mme Lambert, il ne faut jamais manger de chocolat.", "Le bortsch de la mère de Daria contient beaucoup de légumes.", "Fatou va apporter une recette de sa grand-mère."]), ["lis", "coche"], 1, "B",
           sol="Vrai · Faux (un peu, pas tous les jours) · Vrai · Vrai")
    e3 = E("Et toi ? Qu'est-ce que tu manges à midi, en général ? (2 phrases)", lines(2), ["ecris"], 2, "C", sol="Ex. : À midi, je mange à la cantine. Je prends souvent de la soupe et des pâtes.")
    e4 = E("🇧🇪 Les repas en Belgique. Je relie.", relie(["le déjeuner", "le dîner", "le goûter (la collation)", "le souper"], ["le repas du soir", "le repas du matin", "le repas de midi", "un petit repas vers 16 h"]), ["relie"], 1, "B",
           sol="déjeuner → matin · dîner → midi · goûter → vers 16 h · souper → soir (en France : petit-déjeuner, déjeuner, dîner)")
    b.page(f'{e}{e2}{e3}{e4}', "Découvrir")
    menu = f'''<div class="doc" style="transform:none;border:2px solid {MC};background:#fff;padding:3mm 4mm"><div class="flex" style="justify-content:space-between"><div><b style="font-size:13pt;color:{MC}">🍽️ Menu de la cantine · semaine du 23 au 27 novembre</b><br><span class="xs muted">Athénée des Trois Ponts (école fictive) · Repas chaud : 3,80 € · Potage seul : 0,70 €</span></div></div>
{table(["", "Potage", "Plat", "Dessert"], [["<b>Lundi</b>", "potage aux légumes", "pâtes bolognaise · <i>option végétarienne : pâtes aux légumes</i>", "pomme"], ["<b>Mardi</b>", "potage tomate", "filet de poisson, purée de carottes", "yaourt nature"], ["<b>Mercredi</b>", "—", "<i>pas de repas chaud (fin des cours à 12 h 10)</i>", "—"], ["<b>Jeudi</b>", "potage potiron", "stoemp aux poireaux, boulettes (bœuf ou volaille)", "banane"], ["<b>Vendredi</b>", "potage cerfeuil", "riz, curry de lentilles", "gaufre 🧇"]], ["22mm", "36mm", "86mm", "28mm"])}
<p class="xs" style="margin:1mm 0 0">🌾 Allergènes : liste disponible à la cuisine. · 🥛 Lait et eau gratuits. · Inscription au repas : le vendredi précédent, auprès de l'éducateur.</p></div>'''
    e = E("Je lis le menu de la cantine. Je réponds.", menu + f'<p class="mt2">1. Combien coûte un repas chaud ? Et le potage seul ? {blank("l")}</p><p>2. Pourquoi n\'y a-t-il pas de repas le mercredi ? {blank("xl")}</p><p>3. Daria ne mange pas de viande. Quels jours peut-elle manger le plat ? {blank("xl")}</p><p>4. Quel jour préfères-tu ? Pourquoi ? {blank("xl")}</p><p>5. Quand faut-il s\'inscrire ? Auprès de qui ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. 3,80 € ; 0,70 €. — 2. Les cours finissent à 12 h 10. — 3. Lundi (option végétarienne), mardi (poisson, si elle en mange), vendredi (curry de lentilles). — 4. Réponse personnelle. — 5. Le vendredi précédent, auprès de l'éducateur.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Découvrir · Le menu de la cantine</h2>{e}', "Découvrir")

    # ---------- Lexique ----------
    e = E("Les aliments. J'écoute et je répète.", '<div class="grid4">' + "".join(f'<div class="card c" style="padding:2mm"><span class="emo s">{em}</span><b class="sm">{t}</b></div>' for em, t in ALIM) + '</div>', ["ecoute", "repete"], 1, "A",
          script="Lire chaque mot avec l'article. Faire répéter en chœur puis individuellement. Jeu rapide : la prof montre un aliment, les élèves disent le mot avec l'article.", sol="Activité orale.")
    e2 = E("Je classe les aliments de l'exercice précédent.", table(["🥦🍎 Fruits et légumes", "🍞🍚 Céréales, féculents", "🥛🧀 Produits laitiers", "🐟🍗🥚🫘 Protéines"], [["", "", "", ""]], ["46mm", "46mm", "45mm", "45mm"]).replace("<td></td>", '<td style="height:26mm"></td>'), ["ecris"], 1, "C",
           sol="Fruits et légumes : pomme, banane, carotte, brocoli, tomate, oignon · Céréales, féculents : riz, pain, pomme de terre · Produits laitiers : lait, fromage · Protéines : œuf, poisson, poulet, lentilles · (l'huile d'olive = matière grasse)")
    e3 = E("Je trouve l'intrus et j'explique.", '<p>1. la pomme · la banane · <span class="muted">?</span> le poulet · la poire → l\'intrus : ______________ parce que ______________________</p><p>2. le lait · le fromage · le yaourt · le riz → l\'intrus : ______________ parce que ______________________</p><p>3. le pain · les pâtes · le poisson · le riz → l\'intrus : ______________ parce que ______________________</p><p>4. la carotte · le brocoli · l\'œuf · l\'oignon → l\'intrus : ______________ parce que ______________________</p>'.replace(' <span class="muted">?</span>', ''), ["lis", "ecris"], 2, "B",
           sol="1. le poulet (ce n'est pas un fruit) — 2. le riz (ce n'est pas un produit laitier) — 3. le poisson (ce n'est pas une céréale) — 4. l'œuf (ce n'est pas un légume)")
    b.page(f'<h2>Les mots de l\'alimentation</h2>{e}{e2}{e3}', "Lexique")
    l0 = lecon("La pyramide alimentaire (modèle simplifié)", pyramide() + '<div class="grid2 sm mt2" style="gap:1mm 5mm"><p style="margin:0">⬇️ En bas : ce qu\'on mange <b>le plus</b>. ⬆️ En haut : ce qu\'on mange <b>le moins</b>.</p><p style="margin:0">💧 On boit de l\'eau toute la journée (environ <b>1,5 litre</b>).</p><p style="margin:0">🍬 Les sucreries, les sodas, les chips sont des <b>extras</b> : pas interdits, mais <b>rarement</b> et en petite quantité.</p><p style="margin:0">🏃 Et on bouge tous les jours, au moins une heure !</p></div>', label="À OBSERVER")
    e = E("Beaucoup, un peu ou rarement ? J'écris B, U ou R.", '<div class="grid3" style="gap:1mm 6mm"><p>___ les légumes</p><p>___ les bonbons</p><p>___ l\'eau</p><p>___ l\'huile</p><p>___ les sodas</p><p>___ les fruits</p><p>___ le fromage</p><p>___ les chips</p><p>___ le pain complet</p></div>', ["lis", "ecris"], 1, "B",
          sol="B · R · B · U · R · B · U · R · B (à chaque repas)")
    e2 = E("J'observe mon repas d'hier. Il est équilibré ? Qu'est-ce qui manque ? (2 phrases)", lines(2), ["ecris"], 2, "C", sol="Ex. : Hier soir, j'ai mangé du riz et du poulet. Il manquait des légumes.")
    b.page(f'{l0}{e}{e2}', "Lexique")
    e = E("Les saveurs. Je lis et je donne un autre exemple.", table(["", "La saveur", "Exemples", "Mon exemple"], [[f'<span style="font-size:15pt">{a}</span>', f'<b>{w}</b>', d, ""] for a, w, d in SAV], ["12mm", "34mm", "86mm", "50mm"]), ["lis", "ecris"], 1, "C",
          sol="Ex. : sucré : la confiture · salé : les olives · acide : le pamplemousse · amer : le pamplemousse, la bière (pour les adultes) · épicé : le poivre")
    e2 = E("Les plats du monde. Je lis. Je relie l'élève et son plat.", table(["", "Pays", "Un plat"], [[a, f'<b>{p}</b>', d] for a, p, d in MONDE], ["12mm", "40mm", "130mm"]) + '<div class="mt2">' + relie(["Daria", "Bilal", "Mateo", "Yonas"], ["l'injera", "le bortsch", "les arepas", "le kabuli palaw"]) + '</div>', ["lis", "relie"], 1, "B",
           sol="Daria (Ukraine) → le bortsch · Bilal (Afghanistan) → le kabuli palaw · Mateo (Colombie) → les arepas · Yonas (Érythrée) → l'injera")
    e3 = E("Et chez moi ? J'écris le nom d'un plat de mon pays et je le décris avec 2 adjectifs (sucré, salé, épicé, chaud, froid, léger, copieux…).", lines(2), ["ecris"], 2, "C", sol="Ex. : Chez moi, on mange le mafé. C'est un plat salé et copieux.")
    b.page(f'<h2>Les saveurs · les plats du monde</h2>{e}{e2}{e3}', "Lexique")
    ust = [("🔪", "couper", "le couteau"), ("🥄", "mélanger", "la cuillère"), ("🍳", "cuire, faire revenir", "la poêle"), ("🍲", "faire bouillir", "la casserole"), ("🥣", "verser", "le bol, le saladier"), ("🔥", "chauffer", "la plaque, le four"), ("🧂", "ajouter, saler", "le sel"), ("🥔", "éplucher", "l'économe")]
    e = E("Dans la cuisine : les verbes et les ustensiles. J'écoute et je répète.", '<div class="grid4">' + "".join(f'<div class="card c" style="padding:2mm"><span class="emo s">{a}</span><b class="sm">{v}</b><div class="xs muted">{u}</div></div>' for a, v, u in ust) + '</div>', ["ecoute", "repete"], 1, "A",
          script="Lire le verbe puis l'ustensile et mimer chaque geste. Préciser : « éplucher » = enlever la peau ; « l'économe » est le petit couteau pour éplucher.", sol="Activité orale.")
    bel = table(["En Belgique, on dit…", "En France, on dit…", "Exemple"], [["le <b>dîner</b> (midi) · le <b>souper</b> (soir)", "le déjeuner · le dîner", "Je mange à la cantine pour le dîner."], ["un <b>pistolet</b>", "un petit pain rond", "Un pistolet au fromage, s'il vous plaît."], ["une <b>couque</b>", "une viennoiserie", "Une couque au chocolat pour la collation."], ["des <b>chicons</b>", "des endives", "Des chicons au gratin, c'est amer !"], ["un <b>cornet</b> de frites", "un cône, un paquet de frites", "Un cornet de frites avec de la mayonnaise."]], ["58mm", "50mm", "74mm"])
    e2 = E("🇧🇪 Les mots d'ici. Je lis et je réécris la phrase en français de France.", bel + '<p class="mt2">Au souper, on mange des chicons ; au dîner, un pistolet. → __________________________________________</p>', ["lis", "ecris"], 2, "B",
           sol="Au dîner, on mange des endives ; au déjeuner, un petit pain.")
    b.page(f'<h2>Dans la cuisine · les mots d\'ici</h2>{e}{e2}', "Lexique")

    # ---------- Leçon 1 : partitifs ----------
    l1 = lecon("Les articles partitifs : du, de la, de l', des", '''<p>Je ne sais pas la quantité exacte (une partie de quelque chose) → j'utilise un <b>article partitif</b>.</p>
''' + table(["", "Masculin", "Féminin", "Voyelle ou h", "Pluriel"], [["✅", "<b>du</b> pain", "<b>de la</b> soupe", "<b>de l'</b>eau", "<b>des</b> pâtes"], ["❌ négation", "pas <b>de</b> pain", "pas <b>de</b> soupe", "pas <b>d'</b>eau", "pas <b>de</b> pâtes"]], ["30mm", "38mm", "38mm", "38mm", "38mm"]) + '''
<div class="grid2 mt2"><div class="card" style="background:#fff"><b>Exemples</b><p class="sm" style="margin:1mm 0 0">Le matin, je bois <b>du</b> lait et je mange <b>des</b> céréales.<br>Dans le taboulé, il y a <b>de la</b> menthe et <b>du</b> persil.<br>Tu veux <b>de l'</b>eau ? — Non merci, je ne veux pas <b>d'</b>eau.</p></div>
<div class="card" style="background:#fff"><b>⚠️ Attention</b><p class="sm" style="margin:1mm 0 0">Avec <b>aimer, adorer, détester, préférer</b> → le, la, les : J'aime <b>le</b> chocolat. Je mange <b>du</b> chocolat.<br>Je compte → <b>un, une</b> : <b>une</b> pomme, <b>un</b> œuf.</p></div></div>''')
    e = E("Du, de la, de l' ou des ? Je complète.", '<div class="card" style="line-height:1.9">1. Pour le déjeuner, je mange ______ pain avec ______ confiture.<br>2. Ma mère achète ______ carottes et ______ riz.<br>3. Dans le bortsch, il y a ______ betterave et ______ chou.<br>4. Le sportif boit ______ eau.<br>5. Tu prends ______ huile d\'olive pour la salade ?</div>', ["complete"], 1, "C",
          sol="1. du · de la — 2. des · du — 3. de la · du — 4. de l' — 5. de l'")
    b.page(f'{l1}{e}', "Leçon 1")
    e = E("Je réponds à la forme négative.", '<p>1. Tu bois du café ? → Non, je ______________________</p><p>2. Il y a de la viande dans ce plat ? → Non, il ______________________</p><p>3. Vous mangez des bonbons le matin ? → Non, nous ______________________</p><p>4. Elle met de l\'huile ? → Non, elle ______________________</p>', ["ecris"], 1, "C",
          sol="1. je ne bois pas de café. — 2. il n'y a pas de viande. — 3. nous ne mangeons pas de bonbons le matin. — 4. elle ne met pas d'huile.")
    e2 = E("Le, la, les ou du, de la, des ? J'entoure.", '<div class="card big" style="line-height:1.9">1. J\'adore (le / du) fromage, mais ce soir, je ne mange pas (de / du) fromage.<br>2. Yonas mange (l\' / de l\') injera avec (le / du) zigni.<br>3. Je déteste (les / des) chicons !<br>4. Tu veux (la / de la) soupe ?</div>', ["entoure"], 2, "B",
           sol="1. le · de — 2. de l' · du — 3. les — 4. de la")
    e3 = E("J'écoute Fatou au marché. Je coche ce qu'elle achète.", '<div class="grid4" style="gap:1mm 4mm">' + "".join(f'<p><span class="chk"></span> {x}</p>' for x in ["des tomates", "du riz", "de la viande", "des oignons", "de l'huile", "du poisson", "des bananes", "de la pâte d'arachide"]) + '</div>', ["ecoute", "coche"], 2, "A",
           script="« Bonjour Madame ! Je voudrais des tomates et des oignons, s'il vous plaît. Ma grand-mère prépare le riz sauce arachide ce soir. — Vous avez déjà du riz ? — Oui, on en a à la maison. Mais il me faut de la pâte d'arachide et de la viande… pas de poisson, merci. Ah, et de l'huile aussi ! »",
           sol="tomates · viande · oignons · huile · pâte d'arachide (pas : riz, poisson, bananes)")
    e4 = E("Défi ! Qu'est-ce qu'il y a dans mon frigo ? J'écris 5 choses avec du, de la, de l', des, et 2 choses qu'il n'y a pas.", lines(3), ["ecris"], 3, "C", sol="Ex. : Dans mon frigo, il y a du lait, de la sauce tomate, de l'eau, des œufs et du fromage. Il n'y a pas de beurre et pas de jus.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 2 : quantités ----------
    qt = [("⚖️", "un kilo (1 kg) de", "pommes de terre"), ("⚖️", "500 grammes (500 g) de", "carottes"), ("🥛", "un litre (1 L) de", "lait"), ("🧃", "une bouteille de", "jus"), ("🥫", "une boîte de", "tomates"), ("🍫", "une tablette de", "chocolat"),
          ("🥚", "une douzaine d'", "œufs (12)"), ("🍞", "une tranche de", "pain"), ("🥄", "une cuillère de", "sucre"), ("🫙", "un pot de", "yaourt"), ("🧀", "un morceau de", "fromage"), ("🧂", "une pincée de", "sel")]
    l2 = lecon("Les quantités : un kilo de, un peu de, beaucoup de…", '<div class="grid4" style="gap:1.5mm">' + "".join(f'<div class="card" style="padding:1.5mm 2mm;background:#fff"><span style="font-size:13pt">{a}</span> <b class="sm">{q}</b> <span class="sm">{n}</span></div>' for a, q, n in qt) + '''</div>
<div class="grid2 mt2"><div class="card" style="background:#fff"><b>Les quantités imprécises</b><p class="sm" style="margin:1mm 0 0">pas <b>de</b> sucre · <b>un peu de</b> sel · <b>assez de</b> légumes · <b>beaucoup de</b> fruits · <b>trop de</b> sucre</p><p class="sm" style="margin:1mm 0 0">0 → pas de · + → un peu de · ++ → assez de · +++ → beaucoup de · ++++ → trop de 😬</p></div>
<div class="card" style="background:#fff"><b>⚠️ La règle d'or</b><p class="sm" style="margin:1mm 0 0">Après une quantité, toujours <b>de</b> (ou <b>d'</b>) : <br>un kilo <b>de</b> pommes (jamais « un kilo des pommes »)<br>beaucoup <b>d'</b>eau · un peu <b>de</b> farine<br>Pour parler de la quantité sans répéter : <b>en</b> → Tu veux du pain ? Oui, j'<b>en</b> veux deux tranches.</p></div></div>''')
    e = E("Je complète avec une quantité de la leçon.", '<p>1. Pour faire une omelette, il me faut une ______________ d\'œufs.</p><p>2. J\'achète une ______________ d\'eau pétillante.</p><p>3. Au petit-déjeuner, je mange deux ______________ de pain.</p><p>4. Dans la soupe, j\'ajoute une ______________ de sel.</p><p>5. Pour le stoemp, il faut un ______________ de pommes de terre.</p>', ["complete"], 1, "C",
          sol="1. douzaine (ou : demi-douzaine) — 2. bouteille — 3. tranches — 4. pincée — 5. kilo")
    b.page(f'{l2}{e}', "Leçon 2")
    e = E("Un peu de, assez de, beaucoup de, trop de, pas de ? Je regarde le dessin et je complète.", '<div class="card" style="line-height:2">1. 🍬🍬🍬🍬🍬🍬🍬🍬 Dans ce gâteau, il y a ______________ sucre ! 😬<br>2. 🧂 Je mets ______________ sel dans la soupe.<br>3. 🍎🍐🍊🍌🍇 Daria mange ______________ fruits.<br>4. 🚫🥩 Il n\'y a ______________ viande dans le curry de lentilles.<br>5. 💧💧 Tu bois ______________ eau ? Il faut 1,5 litre par jour !</div>', ["complete"], 1, "C",
          sol="1. trop de — 2. un peu de — 3. beaucoup de — 4. pas de — 5. assez d'")
    e2 = E("Je corrige les erreurs (4 erreurs).", '<div class="card big">J\'achète un kilo des carottes, beaucoup du riz, une bouteille de l\'huile et un peu des épices.</div>' + lines(1), ["barre", "ecris"], 2, "C",
           sol="un kilo de carottes, beaucoup de riz, une bouteille d'huile, un peu d'épices")
    e3 = E("Je réponds avec « en ».", '<p>1. Tu veux du jus ? (un verre) → Oui, ______________________</p><p>2. Vous avez des œufs ? (une douzaine) → Oui, ______________________</p><p>3. Il mange des légumes ? (beaucoup) → Oui, ______________________</p><p>4. Tu as de l\'argent ? (non) → Non, ______________________</p>', ["ecris"], 2, "C",
           sol="1. j'en veux un verre. — 2. nous en avons une douzaine. — 3. il en mange beaucoup. — 4. je n'en ai pas.")
    e4 = E("La liste de courses. J'écoute Mme Lambert et j'écris les quantités.", table(["Produit", "Quantité"], [[x, ""] for x in ["pommes de terre", "carottes", "lait", "œufs", "fromage", "chocolat"]], ["80mm", "102mm"]).replace("<td></td>", '<td style="height:6.5mm"></td>'), ["ecoute", "ecris"], 2, "A",
           script="« Pour la fête de la classe, il nous faut : deux kilos de pommes de terre, cinq cents grammes de carottes, un litre de lait, une douzaine d'œufs, un gros morceau de fromage… et trois tablettes de chocolat pour le dessert ! »",
           sol="2 kg · 500 g · 1 L · une douzaine (12) · un gros morceau · 3 tablettes")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 3 : conseiller ----------
    l3 = lecon("Donner un conseil", table(["Pour conseiller…", "Structure", "Exemple"], [
        ["une règle générale", "<b>il faut</b> + infinitif<br><b>il ne faut pas</b> + infinitif", "Il faut boire de l'eau.<br>Il ne faut pas sauter le déjeuner."],
        ["un conseil gentil (plus poli)", "<b>tu devrais / vous devriez</b> + infinitif", "Tu devrais manger plus de fruits.<br>Vous devriez goûter ce plat !"],
        ["comparer deux choix", "<b>il vaut mieux</b> + infinitif", "Il vaut mieux boire de l'eau que du soda."],
        ["un conseil direct", "l'<b>impératif</b> : mange, mangez · <b>évite de</b> + infinitif", "Prends une pomme ! Évite de grignoter devant l'écran."]], ["44mm", "62mm", "76mm"]) + '''
<div class="grid2 mt2"><div class="card" style="background:#fff"><b>Le verbe devoir au conditionnel</b><p class="sm" style="margin:1mm 0 0">je devr<b>ais</b> · tu devr<b>ais</b> · il / elle / on devr<b>ait</b><br>nous devr<b>ions</b> · vous devr<b>iez</b> · ils / elles devr<b>aient</b></p></div>
<div class="card" style="background:#fff"><b>Pour répondre à un conseil</b><p class="sm" style="margin:1mm 0 0">Tu as raison ! · Bonne idée, merci ! · D'accord, je vais essayer. · Oui, mais… (j'aime trop les frites 😅)</p></div></div>''')
    e = E("Je transforme les ordres en conseils gentils avec « tu devrais » ou « vous devriez ».", '<p>1. Mange des légumes ! → ______________________________</p><p>2. Buvez de l\'eau ! → ______________________________</p><p>3. Ne bois pas de soda le matin ! → ______________________________</p><p>4. Prenez un fruit à la récré ! → ______________________________</p>', ["ecris"], 1, "C",
          sol="1. Tu devrais manger des légumes. — 2. Vous devriez boire de l'eau. — 3. Tu ne devrais pas boire de soda le matin. — 4. Vous devriez prendre un fruit à la récré.")
    e0 = E("Je conjugue « devoir » au conditionnel.", '<p>1. Mateo, tu ______________ manger moins de frites. 2. Nous ______________ cuisiner ensemble. 3. Les élèves ______________ prendre le potage. 4. Bilal ______________ boire plus d\'eau. 5. Je ______________ dormir plus. 6. Vous ______________ goûter le taboulé !</p>', ["complete"], 1, "C",
          sol="1. devrais — 2. devrions — 3. devraient — 4. devrait — 5. devrais — 6. devriez")
    b.page(f'{l3}{e}{e0}', "Leçon 3")
    e = E("L'affiche de la cantine. J'écris 4 conseils pour les élèves de l'école (une structure différente par conseil) et je dessine un petit logo.", '<div class="card" style="border:2px dashed ' + MC + '"><p class="c" style="margin:0"><b>🍽️ Bien manger à la cantine : nos conseils</b></p>' + lines(4) + '</div>', ["ecris"], 2, "C",
          sol="Ex. : Il faut prendre le potage. Vous devriez goûter les légumes. Il vaut mieux boire de l'eau que du soda. Évitez de gaspiller : prenez seulement ce que vous allez manger.")
    e2 = E("Un problème, un conseil. Je donne un conseil avec une structure différente à chaque fois.", '<p>1. « Je suis fatigué à 10 h, je ne mange rien le matin. » → ______________________________</p><p>2. « J\'ai toujours faim l\'après-midi. » → ______________________________</p><p>3. « Je bois trois canettes de soda par jour. » → ______________________________</p><p>4. « Je mange devant mon GSM. » → ______________________________</p>', ["ecris"], 2, "C",
           sol="Ex. : 1. Tu devrais prendre un déjeuner : du pain, un fruit. — 2. Il faut prendre une collation saine, une pomme ou un yaourt. — 3. Il vaut mieux boire de l'eau. — 4. Évite de manger devant l'écran : mange avec ta famille.")
    e3 = E("J'écoute 3 conseils à la radio. Je relie la personne et le conseil.", relie(["Léa, 14 ans", "Karim, 15 ans", "Mme Dubois, maman"], ["prendre une collation : un fruit ou des noix", "manger avec les enfants, sans écran", "remplacer le soda par de l'eau"]), ["ecoute", "relie"], 2, "A",
           script="« Bonjour, ici Radio Santé Jeunes (émission fictive). Notre diététicienne répond. — Léa, 14 ans : J'ai faim à 16 h et je mange des chips. — Tu devrais prendre une collation : un fruit ou quelques noix. — Karim, 15 ans : Je bois du soda à tous les repas. — Il vaut mieux le remplacer par de l'eau ! — Mme Dubois : Mes enfants mangent devant la télé. — Il faut manger ensemble, sans écran : c'est meilleur et on parle ! »",
           sol="Léa → collation · Karim → eau au lieu du soda · Mme Dubois → manger ensemble sans écran")
    e4 = E("En duo : jeu de rôle « Chez le diététicien ». A explique ses habitudes, B donne 3 conseils. Puis on échange les rôles.", '<div class="card sm" style="background:#F1F8EE">A : Je mange… je bois… je suis souvent… · B : Vous devriez… Il faut… Il vaut mieux… Évitez de… · A : Merci, je vais essayer !</div>', ["parle", "duo"], 2, "A",
           sol="Évaluer : 3 conseils corrects et variés, vouvoiement, réaction polie.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 4 : recette ----------
    l4 = lecon("Comprendre et écrire une recette", '''<div class="grid2"><div class="card" style="background:#fff"><b>Les parties d'une recette</b><p class="sm" style="margin:1mm 0 0">① le <b>titre</b> (le nom du plat)<br>② le <b>nombre de personnes</b> · le <b>temps</b> de préparation et de cuisson<br>③ les <b>ingrédients</b> avec les <b>quantités</b> (liste)<br>④ les <b>étapes</b> (la préparation), dans l'ordre<br>⑤ parfois une <b>astuce</b>, une photo, un dessin</p></div>
<div class="card" style="background:#fff"><b>Les verbes des étapes</b><p class="sm" style="margin:1mm 0 0">À l'<b>impératif</b> (vous) : <b>Épluchez</b> les carottes. <b>Coupez</b>-les en morceaux.<br>ou à l'<b>infinitif</b> : <b>Éplucher</b> les carottes. <b>Couper</b> en morceaux.<br>⚠️ Dans une recette, je garde la même forme du début à la fin.</p></div></div>
<div class="astuce" style="margin:2mm 0 0">Pour l'ordre : <b>d'abord</b> · <b>ensuite</b> · <b>puis</b> · <b>pendant ce temps</b> · <b>quand</b> c'est cuit · <b>enfin</b>. Pour le temps : pendant 20 minutes · à feu doux · au four à 180 °C.</div>''')
    e = E("Je transforme les étapes : infinitif → impératif (vous).", '<p>1. Laver les tomates. → ______________________ 2. Couper l\'oignon. → ______________________ 3. Mettre l\'huile dans la poêle. → ______________________ 4. Faire cuire 10 minutes. → ______________________ 5. Servir chaud. → ______________________</p>', ["ecris"], 1, "C",
          sol="1. Lavez les tomates. — 2. Coupez l'oignon. — 3. Mettez l'huile dans la poêle. — 4. Faites cuire 10 minutes. — 5. Servez chaud.")
