    tab = '<div class="card" style="background:#FFFDF6;line-height:1.7"><b>🥗 Le taboulé d\'Amina</b> (4 personnes · préparation : 20 min · repos : 30 min)<br>' + "".join(f'<span class="blank s"></span> {t}<br>' for t in ["Ensuite, coupez les tomates, l'oignon, le persil et la menthe en tout petits morceaux.", "D'abord, mettez le boulgour dans un saladier avec un peu d'eau chaude. Attendez 10 minutes.", "Enfin, mettez le taboulé au frigo pendant 30 minutes et servez frais.", "Puis ajoutez les légumes et les herbes au boulgour.", "Mélangez bien avec le jus de deux citrons, de l'huile d'olive et une pincée de sel."]) + '</div>'
    e = E("Je remets les étapes de la recette dans l'ordre (1 à 5).", tab, ["lis", "numerote"], 1, "B", sol="3 · 1 · 5 · 2 · 4")
